INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (401, 101, 'Reservar una mesa', '予約する', 'Pide una mesa para X personas.', 5, 2, 1, '{"activities":[{"id":"ra1","kind":"intro_vocab","word":"予約","reading":"よやく","meaning":"reserva","example":"予約をおねがいします。"},{"id":"ra2","kind":"intro_vocab","word":"二人","reading":"ふたり","meaning":"dos personas","example":"二人です。"},{"id":"rq1","kind":"quiz","prompt":"''Una reserva, por favor'' es…","options":["予約をおねがいします。","予約はどこですか。","予約を食べます。"],"correctIndex":0,"explanation":"〜をおねがいします para pedir cortés."},{"id":"rs1","kind":"speaking","textJp":"二人、おねがいします。","reading":"ふたり、おねがいします","meaning":"Para dos, por favor.","voice":"Kyoko"},{"id":"rsum1","kind":"summary","learned":["予約 (よやく)","二人 (ふたり)","〜をおねがいします"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (402, 101, 'Una mesa junto a la ventana', '席', 'Pide un buen asiento.', 5, 3, 1, '{"activities":[{"id":"rb1","kind":"intro_vocab","word":"席","reading":"せき","meaning":"asiento","example":"窓の席がいいです。"},{"id":"rb2","kind":"intro_vocab","word":"窓","reading":"まど","meaning":"ventana","example":"窓の近く"},{"id":"rq2","kind":"quiz","prompt":"''asiento'' en japonés es…","options":["せき","まど","みせ"],"correctIndex":0,"explanation":"席 = せき = asiento."},{"id":"rs2","kind":"speaking","textJp":"窓の席をおねがいします。","reading":"まどのせきをおねがいします","meaning":"Un asiento junto a la ventana, por favor.","voice":"Otoya"},{"id":"rsum2","kind":"summary","learned":["席 (せき)","窓 (まど)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (403, 101, 'Leer el menú', 'メニュー', 'Entiende el menú y sus secciones.', 5, 4, 1, '{"activities":[{"id":"rc1","kind":"intro_vocab","word":"おすすめ","reading":"おすすめ","meaning":"recomendación","example":"おすすめは何ですか。"},{"id":"rq3","kind":"quiz","prompt":"Para preguntar la recomendación dices…","options":["おすすめは何ですか。","おすすめはどこですか。","おすすめをください。"],"correctIndex":0,"explanation":"何ですか = ¿qué es?"},{"id":"rl1","kind":"listening","textJp":"本日のおすすめです。","voice":"Kyoko","prompt":"¿Qué te dice el mesero?","options":["Es la recomendación de hoy","Está cerrado","Es muy caro"],"correctIndex":0,"explanation":"本日 = hoy; おすすめ = recomendación."},{"id":"rsum3","kind":"summary","learned":["おすすめ (recomendación)","何ですか (¿qué es?)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (404, 101, 'Pedir bebidas', '飲み物', 'Ordena bebidas.', 5, 5, 1, '{"activities":[{"id":"rd1","kind":"intro_vocab","word":"お水","reading":"おみず","meaning":"agua","example":"お水をください。"},{"id":"rd2","kind":"intro_vocab","word":"ビール","reading":"びーる","meaning":"cerveza","example":"ビールをひとつ。"},{"id":"rw1","kind":"write_sentence","prompt":"Pide agua, por favor.","hint":"お水 + を + ください","accepted":["お水をください","お水をください。","おみずをください"],"explanation":"〜をください para pedir."},{"id":"rsum4","kind":"summary","learned":["お水 (おみず)","ビール (cerveza)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (405, 101, 'Hacer tu pedido', '注文', 'Di ''esto, por favor'' señalando el menú.', 5, 6, 1, '{"activities":[{"id":"re1","kind":"intro_vocab","word":"これ","reading":"これ","meaning":"esto","example":"これをください。"},{"id":"rq4","kind":"quiz","prompt":"Señalando el menú, ''esto por favor'' es…","options":["これをください。","これは何ですか。","これはどこですか。"],"correctIndex":0,"explanation":"これ = esto; をください = por favor."},{"id":"rs3","kind":"speaking","textJp":"これをおねがいします。","reading":"これをおねがいします","meaning":"Esto, por favor.","voice":"Kyoko"},{"id":"rsum5","kind":"summary","learned":["これ (esto)","これをください"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (406, 101, 'No puedo comer…', 'アレルギー', 'Avisa de algo que no puedes comer.', 5, 7, 1, '{"activities":[{"id":"rf1","kind":"intro_vocab","word":"食べられません","reading":"たべられません","meaning":"no puedo comer","example":"卵が食べられません。"},{"id":"rf2","kind":"intro_vocab","word":"卵","reading":"たまご","meaning":"huevo","example":"卵料理"},{"id":"rq5","kind":"quiz","prompt":"''No puedo comer huevo'' usa…","options":["食べられません","食べます","飲みます"],"correctIndex":0,"explanation":"食べられません = no poder comer."},{"id":"rsum6","kind":"summary","learned":["食べられません","卵 (たまご)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (407, 101, 'Pedir la cuenta', 'お会計', 'Pide la cuenta al final.', 5, 8, 1, '{"activities":[{"id":"rg1","kind":"intro_vocab","word":"お会計","reading":"おかいけい","meaning":"la cuenta","example":"お会計、おねがいします。"},{"id":"rq6","kind":"quiz","prompt":"Para pedir la cuenta dices…","options":["お会計、おねがいします。","お会計はどこですか。","お会計を食べます。"],"correctIndex":0,"explanation":"お会計 = la cuenta."},{"id":"rs4","kind":"speaking","textJp":"お会計、おねがいします。","reading":"おかいけい、おねがいします","meaning":"La cuenta, por favor.","voice":"Otoya"},{"id":"rsum7","kind":"summary","learned":["お会計 (おかいけい)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (408, 101, 'Pagar', '支払い', 'Paga con tarjeta o efectivo.', 5, 9, 1, '{"activities":[{"id":"rh1","kind":"intro_vocab","word":"カード","reading":"かーど","meaning":"tarjeta","example":"カードでおねがいします。"},{"id":"rh2","kind":"intro_vocab","word":"現金","reading":"げんきん","meaning":"efectivo","example":"現金で払います。"},{"id":"rq7","kind":"quiz","prompt":"''Con tarjeta, por favor'' es…","options":["カードでおねがいします。","カードはどこですか。","カードを食べます。"],"correctIndex":0,"explanation":"で indica el medio: con tarjeta."},{"id":"rsum8","kind":"summary","learned":["カード (tarjeta)","現金 (げんきん)","〜でおねがいします"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (409, 101, 'Estuvo delicioso', 'おいしい', 'Elogia la comida y despídete.', 5, 10, 1, '{"activities":[{"id":"ri1","kind":"intro_vocab","word":"おいしい","reading":"おいしい","meaning":"delicioso","example":"おいしいです。"},{"id":"ri2","kind":"intro_vocab","word":"ごちそうさま","reading":"ごちそうさま","meaning":"gracias por la comida","example":"ごちそうさまでした。"},{"id":"rs5","kind":"speaking","textJp":"おいしかったです。ごちそうさまでした。","reading":"おいしかったです。ごちそうさまでした","meaning":"Estuvo delicioso. Gracias por la comida.","voice":"Kyoko"},{"id":"rsum9","kind":"summary","learned":["おいしい (delicioso)","ごちそうさま (gracias por la comida)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (421, 102, '¿De dónde eres?', '出身', 'Di tu país de origen.', 5, 2, 1, '{"activities":[{"id":"pa1","kind":"intro_vocab","word":"出身","reading":"しゅっしん","meaning":"lugar de origen","example":"メキシコ出身です。"},{"id":"pa2","kind":"intro_vocab","word":"国","reading":"くに","meaning":"país","example":"国はどこですか。"},{"id":"pq1","kind":"quiz","prompt":"''¿De dónde eres?'' es…","options":["出身はどこですか。","出身は何ですか。","出身をください。"],"correctIndex":0,"explanation":"出身 = origen; どこ = dónde."},{"id":"ps1","kind":"speaking","textJp":"メキシコ出身です。","reading":"メキシコしゅっしんです","meaning":"Soy de México.","voice":"Otoya"},{"id":"psum1","kind":"summary","learned":["出身 (しゅっしん)","国 (くに)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (422, 102, 'Tu nombre completo', '名前', 'Di y pregunta el nombre.', 5, 3, 1, '{"activities":[{"id":"pb1","kind":"intro_vocab","word":"名前","reading":"なまえ","meaning":"nombre","example":"お名前は？"},{"id":"pq2","kind":"quiz","prompt":"Para preguntar el nombre, cortés:","options":["お名前は何ですか。","名前はどこですか。","名前を食べます。"],"correctIndex":0,"explanation":"お〜 hace la pregunta más cortés."},{"id":"pw1","kind":"write_sentence","prompt":"Escribe: ''Me llamo Ana.''","hint":"私 + は + アナ + です","accepted":["私はアナです","私はアナです。","わたしはアナです"],"explanation":"X は Y です."},{"id":"psum2","kind":"summary","learned":["名前 (なまえ)","お名前は何ですか"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (423, 102, 'Tu edad', '年齢', 'Di cuántos años tienes.', 5, 4, 1, '{"activities":[{"id":"pc1","kind":"intro_vocab","word":"歳","reading":"さい","meaning":"años (edad)","example":"二十歳です。"},{"id":"pc2","kind":"intro_vocab","word":"何歳","reading":"なんさい","meaning":"¿cuántos años?","example":"何歳ですか。"},{"id":"pq3","kind":"quiz","prompt":"''¿Cuántos años tienes?'' es…","options":["何歳ですか。","何時ですか。","何ですか。"],"correctIndex":0,"explanation":"何歳 = cuántos años."},{"id":"psum3","kind":"summary","learned":["歳 (さい)","何歳 (なんさい)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (424, 102, 'Tu trabajo', '仕事', 'Di a qué te dedicas.', 5, 5, 1, '{"activities":[{"id":"pd1","kind":"intro_vocab","word":"仕事","reading":"しごと","meaning":"trabajo","example":"仕事は何ですか。"},{"id":"pd2","kind":"intro_vocab","word":"会社員","reading":"かいしゃいん","meaning":"empleado de empresa","example":"会社員です。"},{"id":"pq4","kind":"quiz","prompt":"''¿En qué trabajas?'' es…","options":["仕事は何ですか。","仕事はどこですか。","仕事を食べます。"],"correctIndex":0,"explanation":"仕事 = trabajo; 何 = qué."},{"id":"ps2","kind":"speaking","textJp":"会社員です。","reading":"かいしゃいんです","meaning":"Soy empleado de empresa.","voice":"Kyoko"},{"id":"psum4","kind":"summary","learned":["仕事 (しごと)","会社員 (かいしゃいん)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (425, 102, 'Tus pasatiempos', '趣味', 'Habla de lo que te gusta hacer.', 5, 6, 1, '{"activities":[{"id":"pe1","kind":"intro_vocab","word":"趣味","reading":"しゅみ","meaning":"pasatiempo","example":"趣味は音楽です。"},{"id":"pe2","kind":"intro_vocab","word":"映画","reading":"えいが","meaning":"película / cine","example":"映画が好きです。"},{"id":"pw2","kind":"write_sentence","prompt":"Escribe: ''Me gusta el cine.''","hint":"映画 + が + 好き + です","accepted":["映画が好きです","映画が好きです。","えいががすきです"],"explanation":"〜が好きです = me gusta."},{"id":"psum5","kind":"summary","learned":["趣味 (しゅみ)","映画 (えいが)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (426, 102, 'Idiomas que hablas', '言語', 'Di qué idiomas hablas.', 5, 7, 1, '{"activities":[{"id":"pf1","kind":"intro_vocab","word":"スペイン語","reading":"すぺいんご","meaning":"español (idioma)","example":"スペイン語を話します。"},{"id":"pf2","kind":"intro_vocab","word":"話します","reading":"はなします","meaning":"hablar","example":"日本語を話します。"},{"id":"pq5","kind":"quiz","prompt":"''Hablo japonés'' es…","options":["日本語を話します。","日本語を食べます。","日本語はどこですか。"],"correctIndex":0,"explanation":"話します = hablar."},{"id":"psum6","kind":"summary","learned":["スペイン語 (español)","話します (hablar)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (427, 102, 'Mucho gusto', 'はじめまして', 'La frase clave de presentación.', 5, 8, 1, '{"activities":[{"id":"pg1","kind":"intro_vocab","word":"はじめまして","reading":"はじめまして","meaning":"mucho gusto","example":"はじめまして。"},{"id":"ps3","kind":"speaking","textJp":"はじめまして。よろしくおねがいします。","reading":"はじめまして。よろしくおねがいします","meaning":"Mucho gusto. Encantado.","voice":"Otoya"},{"id":"pl1","kind":"listening","textJp":"こちらこそ。","voice":"Kyoko","prompt":"Te responden ''こちらこそ''. Significa…","options":["El gusto es mío","Adiós","No"],"correctIndex":0,"explanation":"こちらこそ = el gusto es mío."},{"id":"psum7","kind":"summary","learned":["はじめまして","よろしくおねがいします"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (428, 102, 'Intercambiar contacto', '連絡先', 'Pide el contacto de alguien.', 5, 9, 1, '{"activities":[{"id":"ph1","kind":"intro_vocab","word":"電話番号","reading":"でんわばんごう","meaning":"número de teléfono","example":"電話番号は？"},{"id":"pq6","kind":"quiz","prompt":"Para pedir el teléfono dices…","options":["電話番号をおしえてください。","電話番号を食べます。","電話番号はおいしいです。"],"correctIndex":0,"explanation":"おしえてください = por favor dime/enséñame."},{"id":"psum8","kind":"summary","learned":["電話番号 (でんわばんごう)","おしえてください"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (429, 102, 'Despedirse', 'さようなら', 'Despídete con cortesía.', 5, 10, 1, '{"activities":[{"id":"pi1","kind":"intro_vocab","word":"また","reading":"また","meaning":"de nuevo / hasta","example":"また明日。"},{"id":"pi2","kind":"intro_vocab","word":"さようなら","reading":"さようなら","meaning":"adiós","example":"さようなら。"},{"id":"ps4","kind":"speaking","textJp":"また明日。さようなら。","reading":"またあした。さようなら","meaning":"Hasta mañana. Adiós.","voice":"Kyoko"},{"id":"psum9","kind":"summary","learned":["また (de nuevo)","さようなら (adiós)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (441, 103, '¿Cuánto cuesta?', 'いくら', 'Pregunta precios.', 5, 2, 1, '{"activities":[{"id":"sa1","kind":"intro_vocab","word":"いくら","reading":"いくら","meaning":"cuánto","example":"いくらですか。"},{"id":"sq1","kind":"quiz","prompt":"''¿Cuánto cuesta esto?'' es…","options":["これはいくらですか。","これは何ですか。","これはどこですか。"],"correctIndex":0,"explanation":"いくら = cuánto."},{"id":"ss1","kind":"speaking","textJp":"これはいくらですか。","reading":"これはいくらですか","meaning":"¿Cuánto cuesta esto?","voice":"Otoya"},{"id":"ssum1","kind":"summary","learned":["いくら (cuánto)"]}]}');
