INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (443, 103, 'Colores', '色', 'Pide otro color.', 5, 4, 1, '{"activities":[{"id":"sc1","kind":"intro_vocab","word":"色","reading":"いろ","meaning":"color","example":"ほかの色は？"},{"id":"sc2","kind":"intro_vocab","word":"黒","reading":"くろ","meaning":"negro","example":"黒いかばん"},{"id":"sw1","kind":"write_sentence","prompt":"Pregunta: ''¿Cuánto cuesta esto?''","hint":"これ + は + いくら + ですか","accepted":["これはいくらですか","これはいくらですか。"],"explanation":"いくらですか = ¿cuánto cuesta?"},{"id":"ssum3","kind":"summary","learned":["色 (いろ)","黒 (くろ)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (444, 103, 'Probarse ropa', '試着', 'Pide probarte algo.', 5, 5, 1, '{"activities":[{"id":"sd1","kind":"intro_vocab","word":"試着","reading":"しちゃく","meaning":"probarse (ropa)","example":"試着してもいいですか。"},{"id":"sq3","kind":"quiz","prompt":"''¿Puedo probármelo?'' es…","options":["試着してもいいですか。","試着はどこですか。","試着を食べます。"],"correctIndex":0,"explanation":"〜てもいいですか = ¿puedo…?"},{"id":"ssum4","kind":"summary","learned":["試着 (しちゃく)","〜てもいいですか"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (445, 103, 'Pagar', '支払い', 'Paga en caja.', 5, 6, 1, '{"activities":[{"id":"se1","kind":"intro_vocab","word":"カード","reading":"かーど","meaning":"tarjeta","example":"カードで。"},{"id":"se2","kind":"intro_vocab","word":"袋","reading":"ふくろ","meaning":"bolsa","example":"袋はいりますか。"},{"id":"sl1","kind":"listening","textJp":"袋はいりますか。","voice":"Kyoko","prompt":"¿Qué te preguntan en caja?","options":["¿Necesita bolsa?","¿Cuánto es?","¿Su nombre?"],"correctIndex":0,"explanation":"袋 = bolsa; いりますか = ¿necesita?"},{"id":"ssum5","kind":"summary","learned":["カード (tarjeta)","袋 (ふくろ)"]}]}');
