INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (449, 103, 'Gracias por su compra', 'ありがとう', 'Cierre cortés de la compra.', 5, 10, 1, '{"activities":[{"id":"si1","kind":"intro_vocab","word":"ありがとう","reading":"ありがとう","meaning":"gracias","example":"ありがとうございます。"},{"id":"sl2","kind":"listening","textJp":"ありがとうございました。","voice":"Kyoko","prompt":"Al pagar te dicen…","options":["Muchas gracias","Bienvenido","Disculpe"],"correctIndex":0,"explanation":"ありがとうございました = muchas gracias."},{"id":"ssum9","kind":"summary","learned":["ありがとう (gracias)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (461, 104, 'Comprar un boleto', '切符', 'Compra tu billete.', 5, 2, 1, '{"activities":[{"id":"ea1","kind":"intro_vocab","word":"切符","reading":"きっぷ","meaning":"boleto","example":"切符をください。"},{"id":"ea2","kind":"intro_vocab","word":"一枚","reading":"いちまい","meaning":"uno (plano)","example":"切符を一枚ください。"},{"id":"eq1","kind":"quiz","prompt":"''Un boleto, por favor'' es…","options":["切符を一枚ください。","切符はどこですか。","切符を食べます。"],"correctIndex":0,"explanation":"一枚 = un (objeto plano)."},{"id":"es1","kind":"speaking","textJp":"東京まで、一枚ください。","reading":"とうきょうまで、いちまいください","meaning":"Uno hasta Tokio, por favor.","voice":"Otoya"},{"id":"esum1","kind":"summary","learned":["切符 (きっぷ)","一枚 (いちまい)","〜まで (hasta)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (462, 104, '¿Dónde está la estación?', '駅', 'Pregunta por la estación.', 5, 3, 1, '{"activities":[{"id":"eb1","kind":"intro_vocab","word":"駅","reading":"えき","meaning":"estación","example":"駅はどこですか。"},{"id":"eq2","kind":"quiz","prompt":"''¿Dónde está la estación?'' es…","options":["駅はどこですか。","駅は何ですか。","駅をください。"],"correctIndex":0,"explanation":"どこ = dónde."},{"id":"es2","kind":"speaking","textJp":"すみません、駅はどこですか。","reading":"すみません、えきはどこですか","meaning":"Disculpe, ¿dónde está la estación?","voice":"Kyoko"},{"id":"esum2","kind":"summary","learned":["駅 (えき)","どこですか"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (463, 104, 'El andén', 'ホーム', 'Encuentra tu andén.', 5, 4, 1, '{"activities":[{"id":"ec1","kind":"intro_vocab","word":"何番線","reading":"なんばんせん","meaning":"¿qué andén/línea?","example":"何番線ですか。"},{"id":"eq3","kind":"quiz","prompt":"''¿Qué andén es?'' es…","options":["何番線ですか。","何時ですか。","何歳ですか。"],"correctIndex":0,"explanation":"何番線 = qué número de vía."},{"id":"esum3","kind":"summary","learned":["何番線 (なんばんせん)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (464, 104, 'Líneas de tren', '電車', 'Identifica la línea correcta.', 5, 5, 1, '{"activities":[{"id":"ed1","kind":"intro_vocab","word":"電車","reading":"でんしゃ","meaning":"tren","example":"電車に乗ります。"},{"id":"ed2","kind":"intro_vocab","word":"乗ります","reading":"のります","meaning":"subir (al tren)","example":"電車に乗ります。"},{"id":"eq4","kind":"quiz","prompt":"''Subo al tren'' es…","options":["電車に乗ります。","電車を食べます。","電車はどこですか。"],"correctIndex":0,"explanation":"に乗ります = subir a."},{"id":"esum4","kind":"summary","learned":["電車 (でんしゃ)","乗ります (のります)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (465, 104, 'El anuncio del tren', 'アナウンス', 'Entiende los anuncios.', 5, 6, 1, '{"activities":[{"id":"ee1","kind":"intro_vocab","word":"次","reading":"つぎ","meaning":"siguiente","example":"次は東京です。"},{"id":"el1","kind":"listening","textJp":"次は東京です。","voice":"Otoya","prompt":"El anuncio dice…","options":["La próxima es Tokio","Puerta cerrada","Llega tarde"],"correctIndex":0,"explanation":"次 = siguiente."},{"id":"esum5","kind":"summary","learned":["次 (つぎ)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (466, 104, 'Transbordo', '乗り換え', 'Cambia de línea.', 5, 7, 1, '{"activities":[{"id":"ef1","kind":"intro_vocab","word":"乗り換え","reading":"のりかえ","meaning":"transbordo","example":"乗り換えはどこですか。"},{"id":"eq5","kind":"quiz","prompt":"''¿Dónde hago transbordo?'' es…","options":["乗り換えはどこですか。","乗り換えを食べます。","乗り換えはおいしいです。"],"correctIndex":0,"explanation":"乗り換え = transbordo."},{"id":"esum6","kind":"summary","learned":["乗り換え (のりかえ)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (467, 104, 'La salida', '出口', 'Encuentra la salida.', 5, 8, 1, '{"activities":[{"id":"eg1","kind":"intro_vocab","word":"出口","reading":"でぐち","meaning":"salida","example":"出口はどこですか。"},{"id":"eg2","kind":"intro_vocab","word":"入口","reading":"いりぐち","meaning":"entrada","example":"入口はあそこです。"},{"id":"ew1","kind":"write_sentence","prompt":"Pregunta: ''¿Dónde está la salida?''","hint":"出口 + は + どこ + ですか","accepted":["出口はどこですか","出口はどこですか。","でぐちはどこですか"],"explanation":"出口 (でぐち) = salida."},{"id":"esum7","kind":"summary","learned":["出口 (でぐち)","入口 (いりぐち)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (468, 104, 'El horario', '時間', 'Pregunta a qué hora sale.', 5, 9, 1, '{"activities":[{"id":"eh1","kind":"intro_vocab","word":"何時","reading":"なんじ","meaning":"¿qué hora?","example":"何時ですか。"},{"id":"eq6","kind":"quiz","prompt":"''¿A qué hora sale?'' empieza con…","options":["何時","何番線","どこ"],"correctIndex":0,"explanation":"何時 = qué hora."},{"id":"esum8","kind":"summary","learned":["何時 (なんじ)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (469, 104, 'Pedir ayuda', 'すみません', 'Pide ayuda con cortesía.', 5, 10, 1, '{"activities":[{"id":"ei1","kind":"intro_vocab","word":"すみません","reading":"すみません","meaning":"disculpe","example":"すみません。"},{"id":"es3","kind":"speaking","textJp":"すみません、ちょっといいですか。","reading":"すみません、ちょっといいですか","meaning":"Disculpe, ¿tiene un momento?","voice":"Kyoko"},{"id":"esum9","kind":"summary","learned":["すみません (disculpe)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (481, 105, 'Pedir un café', 'コーヒー', 'Ordena tu bebida.', 5, 2, 1, '{"activities":[{"id":"ca1","kind":"intro_vocab","word":"コーヒー","reading":"こーひー","meaning":"café","example":"コーヒーをください。"},{"id":"cq1","kind":"quiz","prompt":"''Un café, por favor'' es…","options":["コーヒーをください。","コーヒーはどこですか。","コーヒーを食べます。"],"correctIndex":0,"explanation":"〜をください."},{"id":"cs1","kind":"speaking","textJp":"コーヒーをひとつください。","reading":"こーひーをひとつください","meaning":"Un café, por favor.","voice":"Kyoko"},{"id":"csum1","kind":"summary","learned":["コーヒー (café)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (482, 105, 'Tamaños', 'サイズ', 'Elige el tamaño.', 5, 3, 1, '{"activities":[{"id":"cb1","kind":"intro_vocab","word":"大きい","reading":"おおきい","meaning":"grande","example":"大きいサイズ"},{"id":"cb2","kind":"intro_vocab","word":"小さい","reading":"ちいさい","meaning":"pequeño","example":"小さいサイズ"},{"id":"cq2","kind":"quiz","prompt":"''pequeño'' es…","options":["小さい","大きい","高い"],"correctIndex":0,"explanation":"小さい = ちいさい = pequeño."},{"id":"csum2","kind":"summary","learned":["大きい (grande)","小さい (pequeño)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (483, 105, '¿Para aquí o para llevar?', 'テイクアウト', 'Responde dónde lo tomarás.', 5, 4, 1, '{"activities":[{"id":"cc1","kind":"intro_vocab","word":"ここで","reading":"ここで","meaning":"aquí","example":"ここで飲みます。"},{"id":"cc2","kind":"intro_vocab","word":"持ち帰り","reading":"もちかえり","meaning":"para llevar","example":"持ち帰りで。"},{"id":"cl1","kind":"listening","textJp":"店内ですか、お持ち帰りですか。","voice":"Otoya","prompt":"¿Qué te preguntan?","options":["¿Para aquí o para llevar?","¿Cuánto es?","¿Su nombre?"],"correctIndex":0,"explanation":"店内 = aquí; 持ち帰り = para llevar."},{"id":"csum3","kind":"summary","learned":["ここで (aquí)","持ち帰り (もちかえり)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (484, 105, 'Leche y azúcar', 'ミルク', 'Personaliza tu bebida.', 5, 5, 1, '{"activities":[{"id":"cd1","kind":"intro_vocab","word":"ミルク","reading":"みるく","meaning":"leche","example":"ミルクをおねがいします。"},{"id":"cd2","kind":"intro_vocab","word":"砂糖","reading":"さとう","meaning":"azúcar","example":"砂糖はいりません。"},{"id":"cq3","kind":"quiz","prompt":"''No necesito azúcar'' usa…","options":["いりません","ください","おいしい"],"correctIndex":0,"explanation":"いりません = no necesito."},{"id":"csum4","kind":"summary","learned":["ミルク (leche)","砂糖 (さとう)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (485, 105, 'Postres', 'ケーキ', 'Pide algo dulce.', 5, 6, 1, '{"activities":[{"id":"ce1","kind":"intro_vocab","word":"ケーキ","reading":"けーき","meaning":"pastel","example":"ケーキをください。"},{"id":"cw1","kind":"write_sentence","prompt":"Pide un café, por favor.","hint":"コーヒー + を + ください","accepted":["コーヒーをください","コーヒーをください。","こーひーをください"],"explanation":"〜をください."},{"id":"csum5","kind":"summary","learned":["ケーキ (pastel)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (486, 105, '¿Hay wifi?', 'ワイファイ', 'Pregunta por el wifi.', 5, 7, 1, '{"activities":[{"id":"cf1","kind":"intro_vocab","word":"ワイファイ","reading":"わいふぁい","meaning":"wifi","example":"ワイファイはありますか。"},{"id":"cq4","kind":"quiz","prompt":"''¿Hay wifi?'' es…","options":["ワイファイはありますか。","ワイファイを食べます。","ワイファイはおいしいです。"],"correctIndex":0,"explanation":"ありますか = ¿hay?"},{"id":"csum6","kind":"summary","learned":["ワイファイ (wifi)","ありますか (¿hay?)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (487, 105, 'Esperar el pedido', '待つ', 'Entiende que esperes un momento.', 5, 8, 1, '{"activities":[{"id":"cg1","kind":"intro_vocab","word":"少々お待ちください","reading":"しょうしょうおまちください","meaning":"espere un momento (cortés)","example":"少々お待ちください。"},{"id":"cl2","kind":"listening","textJp":"少々お待ちください。","voice":"Kyoko","prompt":"El barista dice…","options":["Espere un momento","Está cerrado","Gracias"],"correctIndex":0,"explanation":"お待ちください = por favor espere."},{"id":"csum7","kind":"summary","learned":["少々お待ちください (espere un momento)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (488, 105, 'Pagar el café', '支払い', 'Paga en la barra.', 5, 9, 1, '{"activities":[{"id":"ch1","kind":"intro_vocab","word":"全部で","reading":"ぜんぶで","meaning":"en total","example":"全部でいくらですか。"},{"id":"cq5","kind":"quiz","prompt":"''¿Cuánto es en total?'' es…","options":["全部でいくらですか。","全部で何ですか。","全部でどこですか。"],"correctIndex":0,"explanation":"全部で = en total."},{"id":"csum8","kind":"summary","learned":["全部で (en total)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (489, 105, 'Disfruta y despídete', 'また', 'Cierra tu visita al café.', 5, 10, 1, '{"activities":[{"id":"ci1","kind":"intro_vocab","word":"おいしい","reading":"おいしい","meaning":"delicioso","example":"おいしいです。"},{"id":"cs2","kind":"speaking","textJp":"おいしいです。ありがとうございます。","reading":"おいしいです。ありがとうございます","meaning":"Está delicioso. Gracias.","voice":"Kyoko"},{"id":"csum9","kind":"summary","learned":["おいしい (delicioso)","ありがとう (gracias)"]}]}');
